/** @jest-environment node */

const { normalizeFlatKey, SHARED_COMPONENTS_PREFIX } = require('../normalizeFlatKey');

describe('normalizeFlatKey', () => {
  it('exports shared-components prefix constant', () => {
    expect(SHARED_COMPONENTS_PREFIX).toBe('shared-components.');
  });

  it('strips shared-components prefix from flat keys', () => {
    expect(normalizeFlatKey('shared-components.SurveyModal.title')).toBe('SurveyModal.title');
  });

  it('keeps MFE keys unchanged', () => {
    expect(normalizeFlatKey('hub-analytics.homePage.title')).toBe('hub-analytics.homePage.title');
  });
});
